fn generated_java_tool_selector_matches(selector: GeneratedJavaToolSelector, block_id: &str) -> bool {
match selector {
GeneratedJavaToolSelector::Tag(tag_id) => super::is_java_26_2_vanilla_block_in_tag(block_id, tag_id),
GeneratedJavaToolSelector::DirectBlocks(blocks) => blocks
.binary_search_by(|candidate| (*candidate).cmp(block_id))
.is_ok(),
}
}

