fn java_26_2_block_mining_entry(block_id: &str) -> Option<GeneratedJavaBlockMining> {
let index = GENERATED_JAVA_26_2_BLOCK_MINING
.binary_search_by(|candidate| candidate.block_id.cmp(block_id))
.ok()?;
Some(GENERATED_JAVA_26_2_BLOCK_MINING[index])
}

pub(crate) fn java_26_2_block_mining(block_id: &str) -> Option<(f32, bool)> {
let entry = java_26_2_block_mining_entry(block_id)?;
Some((entry.destroy_speed, entry.requires_correct_tool))
}

pub(crate) fn java_26_2_block_render_shape_is_model(block_id: &str) -> Option<bool> {
Some(java_26_2_block_mining_entry(block_id)?.is_model_render_shape)
}

pub(crate) fn java_26_2_block_model_seed_type(block_id: &str) -> Option<&'static str> {
Some(match java_26_2_block_mining_entry(block_id)?.model_seed_type {
GeneratedJavaBlockModelSeedType::Standard => "STANDARD",
GeneratedJavaBlockModelSeedType::DoubleBlockLower => "DOUBLE_BLOCK_LOWER",
GeneratedJavaBlockModelSeedType::BedSource => "BED_SOURCE",
})
}

fn generated_java_26_2_offset_seed(x: i32, z: i32) -> i64 {
let x_component = x.wrapping_mul(3_129_871);
let mut seed = i64::from(x_component)
^ i64::from(z).wrapping_mul(116_129_781);
seed = seed
.wrapping_mul(seed)
.wrapping_mul(42_317_861)
.wrapping_add(seed.wrapping_mul(11));
seed >> 16
}

fn generated_java_26_2_block_model_offset(
offset_type: GeneratedJavaBlockOffsetType,
max_horizontal_offset: f32,
max_vertical_offset: f32,
pos: [i32; 3],
) -> [f32; 3] {
if matches!(offset_type, GeneratedJavaBlockOffsetType::None) {
return [0.0, 0.0, 0.0];
}
let seed = generated_java_26_2_offset_seed(pos[0], pos[2]);
let horizontal_x = (f64::from((seed & 15) as f32 / 15.0) - 0.5) * 0.5;
let horizontal_z = (f64::from(((seed >> 8) & 15) as f32 / 15.0) - 0.5) * 0.5;
let min_horizontal = -f64::from(max_horizontal_offset);
let max_horizontal = f64::from(max_horizontal_offset);
let x = horizontal_x.clamp(min_horizontal, max_horizontal) as f32;
let z = horizontal_z.clamp(min_horizontal, max_horizontal) as f32;
let y = match offset_type {
GeneratedJavaBlockOffsetType::Xz => 0.0,
GeneratedJavaBlockOffsetType::Xyz => {
((f64::from(((seed >> 4) & 15) as f32 / 15.0) - 1.0)
* f64::from(max_vertical_offset)) as f32
}
GeneratedJavaBlockOffsetType::None => unreachable!("NONE returned above"),
};
[x, y, z]
}

pub(crate) fn java_26_2_block_model_offset(
block_id: &str,
pos: [i32; 3],
) -> Option<[f32; 3]> {
let entry = java_26_2_block_mining_entry(block_id)?;
Some(generated_java_26_2_block_model_offset(
entry.offset_type,
entry.max_horizontal_offset,
entry.max_vertical_offset,
pos,
))
}



fn java_26_2_tool_definition(item_id: &str) -> Option<GeneratedJavaToolDefinition> {
let index = GENERATED_JAVA_26_2_TOOL_DEFINITIONS
.binary_search_by(|candidate| candidate.item_id.cmp(item_id))
.ok()?;
Some(GENERATED_JAVA_26_2_TOOL_DEFINITIONS[index])
}

pub(crate) fn java_26_2_tool_mining_speed(item_id: &str, block_id: &str) -> Option<f32> {
let tool = java_26_2_tool_definition(item_id)?;
for rule in tool.rules {
if let Some(speed) = rule.speed
&& generated_java_tool_selector_matches(rule.selector, block_id)
{
return Some(speed);
}
}
Some(tool.default_mining_speed)
}

pub(crate) fn java_26_2_tool_correct_for_drops(item_id: &str, block_id: &str) -> Option<bool> {
let tool = java_26_2_tool_definition(item_id)?;
for rule in tool.rules {
if let Some(correct_for_drops) = rule.correct_for_drops
&& generated_java_tool_selector_matches(rule.selector, block_id)
{
return Some(correct_for_drops);
}
}
Some(false)
}



